use std::collections::HashMap;

struct Solution;

impl Solution {
    pub fn min_stickers(stickers: Vec<String>, target: String) -> i32 {
        // Convert stickers into frequency arrays
        let stickers_freq: Vec<[i32; 26]> = stickers.iter().map(|s| {
            let mut freq = [0; 26];
            for &b in s.as_bytes() {
                if b.is_ascii_lowercase() {
                    freq[(b - b'a') as usize] += 1;
                }
            }
            freq
        }).collect();

        // Frequency array for target
        let mut target_freq = [0; 26];
        for &b in target.as_bytes() {
            if b.is_ascii_lowercase() {
                target_freq[(b - b'a') as usize] += 1;
            }
        }

        // Memoization map: target substring freq -> min stickers
        let mut memo = HashMap::new();

        fn dfs(
            target_freq: &[i32; 26],
            stickers_freq: &Vec<[i32; 26]>,
            memo: &mut HashMap<[i32; 26], i32>,
        ) -> i32 {
            if target_freq.iter().all(|&c| c == 0) {
                return 0;
            }
            if let Some(&res) = memo.get(target_freq) {
                return res;
            }

            let mut ans = i32::MAX;

            // Pick the first letter in target_freq that is > 0 to optimize pruning
            let first_char = target_freq.iter().position(|&c| c > 0).unwrap();

            for sticker in stickers_freq {
                // If sticker doesn't contain the first needed char, skip
                if sticker[first_char] == 0 {
                    continue;
                }

                // Construct new target freq after using this sticker once
                let mut new_target = [0; 26];
                for i in 0..26 {
                    new_target[i] = (target_freq[i] - sticker[i]).max(0);
                }

                let tmp = dfs(&new_target, stickers_freq, memo);
                if tmp != -1 {
                    ans = ans.min(1 + tmp);
                }
            }

            let res = if ans == i32::MAX { -1 } else { ans };
            memo.insert(*target_freq, res);
            res
        }

        dfs(&target_freq, &stickers_freq, &mut memo)
    }
}

